        : <section>Derived fallback {rows.flatMap(row => [<b key={row.id}>Top {row.name}</b>, <Fragment key={row.id + "-tail"}>Tail {row.value}</Fragment>])}</section>}
      <Forms n={count} one="entry" other={<b>Entries {account.name}</b>} />
    </Derived> after {count}</main><Value>{account.name}</Value></section>;
    }

