        return <Shell ready={this.#ready} fallback={this.fallback} preview={this.preview}><Fragment key={key}>Start {rows.map(row => [
      <Fragment key={row.id}><h3>Heading {row.name}</h3>{enabled && <Choice branch={mode} one={<b>Owned {account.name}</b>} other={fallback} />}</Fragment>,
      row.open ? <section key={row.id + '-open'}>Open {enabled && <Choice branch={mode} one={<b>Owned {account.name}</b>} other={fallback} />}</section> : null,
    ])}<><p>Fragment sibling {count}</p><Choice branch={mode} first={enabled && <Choice branch={mode} one={<b>Owned {account.name}</b>} other={fallback} />} other="End" /></></Fragment></Shell>;
      }
    }

